static __inline__ int sceKernelProfilerReset(SceProfilerRegs *pRegs)
{
        unsigned int en;

        en = pRegs->en;
        pRegs->en = 0U;
        __builtin_allegrex_sync();

        pRegs->n_ck = 0U;
        pRegs->n_gck = 0U;
        pRegs->n_stalli = 0U;
        pRegs->n_stallm = 0U;
        pRegs->n_slipc = 0U;
        pRegs->n_stallc = 0U;
        pRegs->n_sleep = 0U;
        pRegs->n_bus = 0U;
        pRegs->n_uld = 0U;
        pRegs->n_ust = 0U;
        pRegs->n_cld = 0U;
        pRegs->n_cst = 0U;
        pRegs->n_imiss = 0U;
        pRegs->n_dmiss = 0U;
        pRegs->n_wbk = 0U;
        pRegs->n_cop0 = 0U;
        pRegs->n_fpu = 0U;
        pRegs->n_vfpu = 0U;
        __builtin_allegrex_sync();

        return ((int)en);

}

static __inline__ int sceKernelProfilerStart(SceProfilerRegs *pRegs)
{
        unsigned int en;

        en = pRegs->en;
        {if (en==0U) {{
                pRegs->en = 1U;
                __builtin_allegrex_sync();

        }}}

        return ((int)en);

}

static __inline__ int sceKernelProfilerStop(SceProfilerRegs *pRegs)
{
        unsigned int en;

        en = pRegs->en;
        {if (en!=0U) {{
                pRegs->en = 0U;
                __builtin_allegrex_sync();

        }}}

        return ((int)en);

}

static __inline__ unsigned int sceKernelProfilerGetSystemClockCycle(const SceProfilerRegs *pRegs)
{
        return (pRegs->n_ck);
}

