static __inline__ void sceKernelDcacheMemcpyInline(void *dest, const void *src, unsigned int size)
{
        unsigned int dend;
        __asm__ volatile (
                ".set			push\n"
                ".set			noreorder\n"
                ".set			noat\n"
                "or				%3,  %0,  %1\n"
                "ext			%3,  %0,  30,  1\n"
                "bne			%3,  $0,  3f\n"
                "addu			%3,  %0,  %2\n"
                "sltu			$1,  %2,  128\n"
                "bnez			$1,  2f\n"
                "xor			$1,  %0,  %1\n"
                "andi			$1,  $1,  0x0003\n"
                "bne			$1,  $0,  3f\n"
                "addiu			%2,  %0,  63\n"
                "ins			%2,  $0,  0, 6\n"
        "0:\n"
                "beq			%2,  %0,  8f\n"
                "lbu			$1,   0(%1)\n"
                "addiu			%0,  %0,  1\n"
                "addiu			%1,  %1,  1\n"
                "j				0b\n"
                "sb				$1,  -1(%0)\n"
        "8:\n"
                "move			$1,  %3\n"
                "ins			$1,  $0,  0,  6\n"
        "1:\n"
                "cache			0x18, 0(%0)\n"
                "lw				%2,   0(%1)\n"
                "sw				%2,   0(%0)\n"
                "lw				%2,   4(%1)\n"
                "sw				%2,   4(%0)\n"
                "lw				%2,   8(%1)\n"
                "sw				%2,   8(%0)\n"
                "lw				%2,  12(%1)\n"
                "sw				%2,  12(%0)\n"
                "lw				%2,  16(%1)\n"
                "sw				%2,  16(%0)\n"
                "lw				%2,  20(%1)\n"
                "sw				%2,  20(%0)\n"
                "lw				%2,  24(%1)\n"
                "sw				%2,  24(%0)\n"
                "lw				%2,  28(%1)\n"
                "sw				%2,  28(%0)\n"
                "lw				%2,  32(%1)\n"
                "sw				%2,  32(%0)\n"
                "lw				%2,  36(%1)\n"
                "sw				%2,  36(%0)\n"
                "lw				%2,  40(%1)\n"
                "sw				%2,  40(%0)\n"
                "lw				%2,  44(%1)\n"
                "sw				%2,  44(%0)\n"
                "lw				%2,  48(%1)\n"
                "sw				%2,  48(%0)\n"
                "lw				%2,  52(%1)\n"
                "sw				%2,  52(%0)\n"
                "lw				%2,  56(%1)\n"
                "sw				%2,  56(%0)\n"
                "addiu			%0,  %0,  64\n"
                "lw				%2,  60(%1)\n"
                "addiu			%1,  %1,  64\n"
                "bne			%0,  $1,  1b\n"
                "sw				%2,  60-64(%0)\n"
        "2:\n"
                "beq			%0,  %3,  9f\n"
                "nop\n"
        "3:\n"
                "addiu			%0,  %0,  1\n"
                "lbu			%2,   0(%1)\n"
                "addiu			%1,  %1,  1\n"
                "bne			%0,  %3,  3b\n"
                "sb				%2,  -1(%0)\n"
        "9:\n"
                ".set			pop\n"
                : "+r"(dest), "+r"(src), "+r"(size), "=&r"(dend)
                :
                : "memory", "$1"
        );
        return;
}

